css:
.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.gradient-panel {
  padding: 32px;
  border-radius: 18px;
  color: #fff;
  background:
    radial-gradient(circle at 90% 10%, #ffffff40, transparent 50%),
    linear-gradient(135deg, #4338ca, #0f766e);
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.shadow-panel {
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface);
  box-shadow:
    0 2px 5px #0000000c,
    0 18px 38px #00000014;
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.gradient-border {
  border: 3px solid transparent;
  border-radius: 18px;
  padding: 24px;
  background:
    linear-gradient(var(--surface), var(--surface)) padding-box,
    linear-gradient(120deg, #6366f1, #0d9488) border-box;
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.pseudo-card {
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: 12px;
}
.pseudo-card h3::before {
  content: "✦";
  margin-inline-end: 8px;
  color: var(--primary);
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.image-overlay {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 16px;
  padding: 40px 24px;
  background: linear-gradient(135deg, #0f766e, #4338ca);
  color: white;
}
.image-overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(0deg, #0009, transparent);
  pointer-events: none;
}
.image-overlay a {
  color: white;
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.pattern-bg {
  padding: 24px;
  border-radius: 16px;
  background: repeating-linear-gradient(
    45deg,
    var(--soft) 0 8px,
    var(--surface) 8px 16px
  );
}
.pattern-bg > * {
  background: var(--surface);
  padding: 10px;
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.has-choice {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px;
  border: 2px solid var(--border);
  border-radius: 12px;
}
.has-choice input:checked + span {
  font-weight: 700;
}
@supports selector(:has(*)) {
  .has-choice:has(input:checked) {
    border-color: var(--primary);
    background: var(--soft);
  }
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
@layer base, components, utilities;
@layer base {
  .layer-card {
    padding: 24px;
    border: 2px solid var(--border);
  }
}
@layer components {
  .layer-card {
    border-color: var(--primary);
    border-radius: 12px;
  }
}
@layer utilities {
  .layer-card {
    border-style: dashed;
  }
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.cqi-parent {
  container-type: inline-size;
  padding: 20px;
  border: 1px solid var(--border);
}
.cqi-title {
  font-size: 1.5rem;
}
@supports (font-size: 1cqi) {
  .cqi-title {
    font-size: clamp(1.25rem, calc(1rem + 3cqi), 2.5rem);
  }
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.anchor-scroll {
  max-height: 220px;
  overflow: auto;
  scroll-padding-block-start: 20px;
  border: 1px solid var(--border);
}
.anchor-scroll section {
  min-height: 200px;
  padding: 20px;
  scroll-margin-block-start: 20px;
}
.anchor-scroll :target {
  background: var(--soft);
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.visibility-list {
  max-height: 300px;
  overflow: auto;
}
.visibility-list article {
  padding: 24px;
  margin-block-end: 12px;
  border: 1px solid var(--border);
  content-visibility: auto;
  contain-intrinsic-size: auto 160px;
}

.recipe-demo {
  display: grid;
  gap: 16px;
  min-width: 0;
}
.viewport-shell {
  min-height: 60vh;
  min-height: 60dvh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.viewport-shell > * {
  padding: 16px;
}
.viewport-shell header,
.viewport-shell footer {
  background: var(--soft);
}
